.tgi-blk_ksv2jxn{
  --paper:#FAFAF5;
  --ink:#17161B;
  --cobalt:#2F45E0;
  --pink:#FF5E7A;
  --acid:#FFD84D;
  --rule:2px solid var(--ink);
  --display:"Bricolage Grotesque", sans-serif;
  --body:"Figtree", sans-serif;
}
.tgi-blk_ksv2jxn *{margin:0;padding:0;box-sizing:border-box;}
.tgi-blk_ksv2jxn{scroll-behavior:smooth;}
.tgi-blk_ksv2jxn{
  font-family:var(--body);
  background:var(--paper);
  color:var(--ink);
  font-size:16px;
  line-height:1.5;
  -webkit-font-smoothing:antialiased;
}
.tgi-blk_ksv2jxn img{display:block;max-width:100%;}
.tgi-blk_ksv2jxn a{color:inherit;}
.tgi-blk_ksv2jxn :focus-visible{outline:3px solid var(--cobalt);outline-offset:3px;}
.tgi-blk_ksv2jxn ::selection{background:var(--acid);}
.tgi-blk_ksv2jxn .nav{
  background:var(--ink);
  color:var(--paper);
  display:flex;
  align-items:center;
  gap:28px;
  padding:0 clamp(16px,4vw,48px);
  height:64px;
  position:sticky;
  top:0;
  z-index:50;
  border-bottom:var(--rule);
}
.tgi-blk_ksv2jxn .nav__logo{
  font-family:var(--display);
  font-weight:800;
  font-size:22px;
  letter-spacing:-0.01em;
  text-decoration:none;
  display:flex;
  align-items:baseline;
  gap:6px;
}
.tgi-blk_ksv2jxn .nav__logo em{font-style:normal;color:var(--acid);}
.tgi-blk_ksv2jxn .nav__links{display:flex;gap:4px;list-style:none;margin-right:auto;}
.tgi-blk_ksv2jxn .nav__links a{
  text-decoration:none;
  font-weight:600;
  font-size:14.5px;
  padding:10px 12px;
  display:inline-block;
}
.tgi-blk_ksv2jxn .nav__links a:hover{background:var(--cobalt);}
.tgi-blk_ksv2jxn .nav__phone{
  font-size:13.5px;
  font-weight:600;
  text-decoration:none;
  color:var(--paper);
  opacity:.85;
  white-space:nowrap;
}
.tgi-blk_ksv2jxn .nav__phone:hover{opacity:1;text-decoration:underline;}
.tgi-blk_ksv2jxn .btn{
  font-family:var(--display);
  font-weight:700;
  font-size:15px;
  text-decoration:none;
  background:var(--acid);
  color:var(--ink);
  border:2px solid var(--ink);
  padding:11px 20px;
  display:inline-block;
  cursor:pointer;
  white-space:nowrap;
  transition:transform .15s ease-out, background .15s ease-out;
}
.tgi-blk_ksv2jxn .btn:hover{transform:translate(-2px,-2px);box-shadow:4px 4px 0 var(--pink);}
.tgi-blk_ksv2jxn .btn:active{transform:translate(0,0);box-shadow:none;}
.tgi-blk_ksv2jxn h1{
  font-family:var(--display);
  font-weight:800;
  font-size:clamp(44px,6vw,86px);
  line-height:.95;
  letter-spacing:-0.03em;
  max-width:12ch;
}
.tgi-blk_ksv2jxn h2{
  font-family:var(--display);
  font-weight:800;
  font-size:clamp(28px,4vw,46px);
  letter-spacing:-0.02em;
  line-height:1;
}
.tgi-blk_ksv2jxn footer{
  background:var(--ink);
  color:var(--paper);
  margin-top:clamp(48px,7vw,88px);
  border-top:var(--rule);
  padding:clamp(36px,5vw,64px) clamp(16px,4vw,48px) 28px;
}

@media (prefers-reduced-motion: reduce){
  .tgi-blk_ksv2jxn{scroll-behavior:auto;}
  .tgi-blk_ksv2jxn .btn:hover{transform:none;}
  .tgi-blk_ksv2jxn *{transition-duration:0.01ms !important;}
}
@media (max-width:860px){
  .tgi-blk_ksv2jxn .nav__links{display:none;}
  .tgi-blk_ksv2jxn .nav__phone{margin-left:auto;}
}
@media (max-width:640px){
  .tgi-blk_ksv2jxn .nav{gap:12px;}
  .tgi-blk_ksv2jxn .nav .btn{padding:11px 13px;font-size:14px;}
}
@media (max-width:380px){
  .tgi-blk_ksv2jxn .nav__phone{display:none;}
}

